/// assets/config.json 설정값
class Config {
  final Map<String, dynamic> values;
  Config(this.values);

  factory Config.load([String path = 'assets/config.json']) =>
      Config(jsonDecode(File(path).readAsStringSync()) as Map<String, dynamic>);
