/// 장치 이름 변경
class Device {
  String name;
  Device(this.name);

  void rename(String newName) {
    name = newName;
  }
}

/// 펌웨어 업데이트
class Board {
  final String type;
  final String version;
  Board(this.type, this.version);
}

class FirmwareFile {
  final String version;
  FirmwareFile(this.version);
}

class FwUpdater {
  /// 업데이트를 시작하고 결과 버전을 돌려준다
  String start(Board board, FirmwareFile file) => file.version;
}

/// 점검 로그 저장 · 보관
class LogStore {
  static const keepDays = 30;
  final List<(DateTime, String)> entries = [];

  void write(String message, [DateTime? at]) {
    entries.add((at ?? DateTime.now(), message));
  }

  /// 보관 기간이 지난 로그 삭제
  void cleanup([DateTime? now]) {
    final limit = (now ?? DateTime.now()).subtract(const Duration(days: keepDays));
    entries.removeWhere((e) => e.$1.isBefore(limit));
  }
}

