#!/usr/bin/env node
// 병합 요청(PR)을 올리기 직전에 "개발자 이해 확인"이 채워졌는지 확인한다. 비어 있으면 PR을 올리지 않는다 (종료 코드 2).
// - AI 도구가 `gh pr create --body-file <파일>` 을 실행하려 할 때 동작 (Claude Code PreToolUse · Gemini CLI BeforeTool 공용)
// - 답은 /hdel-ai-coding:병합요청 이 대화에서 개발자에게 받아 원문 그대로 넣는다. 이 스크립트는 빈칸만 막는다
// - 건너뜀: AI 미사용 PR, 제목이 [긴급](병합 뒤 작성) · [기준선](유지보수 적용, 담당자 보완으로 대신) 인 PR
// - AGENTS.md 에 "조직: 비개발" 이 있으면 1문항(어떻게 확인했나)
const fs = require("fs"), path = require("path");

let input = {};
try { input = JSON.parse(fs.readFileSync(0, "utf8")); } catch { process.exit(0); }
const cmd = (input.tool_input && input.tool_input.command) || "";
if (!/\bgh\s+pr\s+create\b/.test(cmd)) process.exit(0);

const block = msg => { process.stderr.write(msg + "\n"); process.exit(2); };
const root = process.env.CLAUDE_PROJECT_DIR || process.env.GEMINI_PROJECT_DIR || input.cwd || process.cwd();
const fileArg = cmd.match(/--body-file[=\s]+(?:"([^"]+)"|'([^']+)'|(\S+))/);
if (!fileArg) block("PR 본문은 --body-file 로 올립니다. /hdel-ai-coding:병합요청 으로 PR을 만드세요.");
const base = input.tool_input.dir_path ? path.resolve(root, input.tool_input.dir_path) : (input.cwd || root);  // Gemini run_shell_command 의 실행 폴더
const bodyFile = path.resolve(base, fileArg[1] || fileArg[2] || fileArg[3]);
if (!fs.existsSync(bodyFile)) block(`PR 본문 파일이 없습니다: ${bodyFile}`);
const body = fs.readFileSync(bodyFile, "utf8");
const title = (cmd.match(/--title[=\s]+(?:"([^"]*)"|'([^']*)')/) || [])[1] || "";
if (/^\[(긴급|기준선)\]/.test(title) || !/\[x\] 사용함/.test(body)) process.exit(0);

const agentsPath = path.join(root, "AGENTS.md");
const nonDev = fs.existsSync(agentsPath) && /조직:\s*비개발/.test(fs.readFileSync(agentsPath, "utf8"));
const QS = nonDev ? ["어떻게 확인했나"] : ["핵심 로직은 어떻게 동작하는가", "우려되는 문제점은 무엇인가", "왜 이 방식을 골랐는가 (검토한 대안)"];
const empty = QS.filter(q => { const m = body.match(new RegExp(`^- ${q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}:(.*)$`, "m")); return !m || !m[1].trim(); });
if (empty.length) block(`개발자 이해 확인이 비어 있어 PR을 올리지 않았습니다: ${empty.join(" / ")}\n개발자에게 이 문항을 물어, 받은 답을 고치지 말고 그대로 PR 본문에 넣은 뒤 다시 올리세요. 긴급이면 /hdel-ai-coding:병합긴급 을 쓰세요.`);
process.exit(0);
